mapper.select:
SELECT /*+ LEADING(U D M D3) USE_NL(D M D3) INDEX(D) PUSH_PRED(D3) */ U.EMP_NO AS EMP_NO, M.TRIP_REQ_NO AS TRIP_REQ_NO, D.TRIP_ST_DTM, D.TRIP_ED_DTM, M.TRIP_PLACE, M.APRV_STS_CD, NVL(D3.EQUIP_NM, M.EQUIP_NM) AS EQUIP_NM, NVL(D3.CLNT_PJT, M.CLNT_PJT) AS CLNT_PJT, NVL(D3.CLNT_PJT_NM, FN_CM05M01_CD_TO_NM(M.CLNT_PJT)) AS CLNT_PJT_NM, NVL(D3.SALES_CD, M.SALES_CD) AS SALES_CD, NVL(D3.ORDRS_NO, M.SALES_CD) AS ORDRS_NO, D3.ST_DT, D3.ED_DT, D3.MD, M.TRIP_DIV, FN_CM05M01_CD_TO_NM(M.TRIP_DIV) AS TRIP_DIV_NM, M.TRIP_TYPE_CDS, FN_CM05M01_CD_TO_NM(M.TRIP_TYPE_CDS) AS TRIP_TYPE_NM FROM TB_CM06M01 U INNER JOIN TB_PM51D01 D ON D.USER_ID = U.ID INNER JOIN TB_PM51M01 M ON M.TRIP_REQ_NO = D.TRIP_REQ_NO LEFT OUTER JOIN ( SELECT TRIP_REQ_NO, ST_DT, ED_DT, EQUIP_NM, CLNT_PJT, CLNT_PJT_NM, SALES_CD, ORDRS_NO, MD, ROW_NUMBER() OVER(PARTITION BY TRIP_REQ_NO, ST_DT, ED_DT ORDER BY SEQ ASC) AS RN FROM TB_PM51D03 WHERE ST_DT <= #{edDt, jdbcType=VARCHAR} AND ED_DT >= #{stDt, jdbcType=VARCHAR} ) D3 ON D3.TRIP_REQ_NO = D.TRIP_REQ_NO AND D3.RN = 1 WHERE U.EMP_NO IN
#{item, jdbcType=VARCHAR}
AND D.TRIP_ST_DTM <= #{edDt, jdbcType=VARCHAR} || '999999' AND D.TRIP_ED_DTM >= #{stDt, jdbcType=VARCHAR} || '000000' ORDER BY D.TRIP_ST_DTM ASC

SELECT U.EMP_NO AS EMP_NO, M.REQ_NO AS REQ_NO, D.VAC_DT, M.VAC_TYPE_CD, (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = M.VAC_TYPE_CD) AS VAC_TYPE_NM, M.AMPM_CD, M.SANCTN_STS, D.WORK_HOUR FROM TB_PM07M03 D INNER JOIN TB_PM07M01 M ON M.CO_CD = D.CO_CD AND M.REQ_NO = D.REQ_NO INNER JOIN TB_CM06M01 U ON U.ID = M.REQ_ID WHERE U.EMP_NO IN
#{item, jdbcType=VARCHAR}
AND D.VAC_DT >= #{stDt, jdbcType=VARCHAR} AND D.VAC_DT <= #{edDt, jdbcType=VARCHAR} ORDER BY D.VAC_DT ASC

SELECT /*+ LEADING(U D M D3) USE_NL(D M R D3) INDEX(D) PUSH_PRED(D3) */ U.EMP_NO AS EMP_NO, M.TRIP_RPT_NO AS TRIP_RPT_NO, M.TRIP_REQ_NO AS TRIP_REQ_NO, D.TRIP_ST_DTM, D.TRIP_ED_DTM, R.TRIP_PLACE, M.APRV_STS_CD, NVL(D3.EQUIP_NM, R.EQUIP_NM) AS EQUIP_NM, NVL(D3.CLNT_PJT, R.CLNT_PJT) AS CLNT_PJT, NVL(D3.CLNT_PJT_NM, FN_CM05M01_CD_TO_NM(R.CLNT_PJT)) AS CLNT_PJT_NM, NVL(D3.SALES_CD, R.SALES_CD) AS SALES_CD, NVL(D3.ORDRS_NO, R.SALES_CD) AS ORDRS_NO, D3.ST_DT, D3.ED_DT, D3.MD, R.TRIP_DIV, FN_CM05M01_CD_TO_NM(R.TRIP_DIV) AS TRIP_DIV_NM, R.TRIP_TYPE_CDS, FN_CM05M01_CD_TO_NM(R.TRIP_TYPE_CDS) AS TRIP_TYPE_NM FROM TB_CM06M01 U INNER JOIN TB_PM52D02 D ON D.USER_ID = U.ID INNER JOIN TB_PM52M01 M ON M.TRIP_RPT_NO = D.TRIP_RPT_NO LEFT OUTER JOIN TB_PM51M01 R ON R.TRIP_REQ_NO = M.TRIP_REQ_NO LEFT OUTER JOIN ( SELECT TRIP_RPT_NO, ST_DT, ED_DT, EQUIP_NM, CLNT_PJT, CLNT_PJT_NM, SALES_CD, ORDRS_NO, MD, ROW_NUMBER() OVER(PARTITION BY TRIP_RPT_NO, ST_DT, ED_DT ORDER BY SEQ ASC) AS RN FROM TB_PM52D03 WHERE ST_DT <= #{edDt, jdbcType=VARCHAR} AND ED_DT >= #{stDt, jdbcType=VARCHAR} ) D3 ON D3.TRIP_RPT_NO = D.TRIP_RPT_NO AND D3.RN = 1 WHERE U.EMP_NO IN
#{item, jdbcType=VARCHAR}
AND D.TRIP_ST_DTM <= #{edDt, jdbcType=VARCHAR} || '999999' AND D.TRIP_ED_DTM >= #{stDt, jdbcType=VARCHAR} || '000000' ORDER BY D.TRIP_ST_DTM ASC

SELECT
	A.WORK_DT,
	A.EMP_NO
FROM TB_PM30M01 A
WHERE A.CO_CD = #{coCd, jdbcType=VARCHAR}
  AND A.WORK_DT >= #{stDt, jdbcType=VARCHAR}
  AND A.WORK_DT <= #{edDt, jdbcType=VARCHAR}

  AND A.EMP_NO IN

	#{item, jdbcType=VARCHAR}
